This class is a custom `LayerDrawable` in Android that stacks multiple drawables (icons) on top of each other, with the first two icons being reversed and scaled down.

In Swift, you can create a similar class using `CALayer` and `UIImage` instead of `LayerDrawable` and `Drawable`. Here's a basic example:

```swift
import UIKit

class StackedLayers {
    private var layers: [CALayer] = []
    private let iconScale: CGFloat = 0.7

    init(layers: [UIImage], iconScale: CGFloat = 0.7) {
        self.layers = layers.map { CALayer() }
        self.iconScale = iconScale
        setupLayers()
    }

    func setupLayers() {
        for (index, layer) in layers.enumerated() {
            let imageLayer = CALayer()
            imageLayer.contents = layer.cgImage
            imageLayer.frame = bounds
            imageLayer.bounds = CGRect(origin: .zero, size: CGSize(width: bounds.width * iconScale, height: bounds.height * iconScale))
            imageLayer.position = CGPoint(x: bounds.midX, y: bounds.midY)

            switch index {
            case 1:
                imageLayer.frame.origin.x = 0
                imageLayer.frame.origin.y = bounds.height - bounds.width * iconScale
            case 0:
                imageLayer.frame.origin.x = bounds.width - bounds.width * iconScale
                imageLayer.frame.origin.y = 0
            default:
                break
            }

            self.layers[index] = imageLayer
        }
    }

    var bounds: CGRect {
        didSet {
            for layer in layers {
                layer.frame = CGRect(origin: layer.frame.origin, size: layer.bounds.size)
                layer.bounds = CGRect(origin: .zero, size: layer.bounds.size)
            }
            setupLayers()
        }
    }
}
```

